input.command:
cd /home/user/rork-app

# Re-mint owner token if needed
curl -s -X POST https://api.ivxholding.com/api/ivx/owner-passwordless-login \
  -H "Content-Type: application/json" -d '{"email":"iperez4242@gmail.com"}' \
  -o /tmp/login.json -w "login HTTP %{http_code}\n"
node -e "const d=JSON.parse(require('fs').readFileSync('/tmp/login.json','utf8')); if(!d.accessToken){console.log('LOGIN FAILED', JSON.stringify(d).slice(0,200)); process.exit(1);} require('fs').writeFileSync('/tmp/owner_at', d.accessToken);"
export OWNER_TOKEN=$(cat /tmp/owner_at)

echo "=== Committing senior dev fix files to GitHub ==="
cat > /tmp/commit-senior-dev-fix.mjs <<'EOF'
import { gzipSync } from 'node:zlib';
import { readFileSync } from 'node:fs';
const OWNER_TOKEN = process.env.OWNER_TOKEN;
const files = [
  { path: 'backend/services/ivx-senior-developer-runtime.ts', msg: 'IVX senior dev fix: deploy-only redeploy when no code change but user asks to deploy live; stop returning BLOCKED with "no code change required"' },
  { path: 'backend/services/ivx-senior-developer-answer-format.ts', msg: 'IVX senior dev fix: answer format shows LOCAL ONLY for no-code/no-deploy, DEPLOYED for deploy-only redeploy, not BLOCKED' },
  { path: 'backend/services/ivx-senior-developer-answer-format.test.ts', msg: 'IVX senior dev fix: update tests for LOCAL ONLY no-code case + add deploy-only DEPLOYED regression test' },
];
for (const f of files) {
  const content = readFileSync(f.path);
  const gz = gzipSync(content).toString('base64');
  const r = await fetch('https://api.ivxholding.com/api/ivx/developer-deploy/action', {
    method: 'POST',
    headers: { 'Authorization': `Bearer ${OWNER_TOKEN}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({ action: 'github_commit_file', input: { path: f.path, content: gz, contentEncoding: 'gzip-base64', message: f.msg }, confirm: true, confirmText: 'CONFIRM_IVX_GITHUB_WRITE' })
  });
  const t = await r.text();
  try {
    const j = JSON.parse(t);
    console.log(`${f.path}: HTTP ${r.status} ok=${j.ok} sha=${(j.output?.commitSha||j.commitSha||'').slice(0,12)} error=${j.error||''}`);
  } catch { console.log(`${f.path}: HTTP ${r.status} ${t.slice(0,300)}`); }
}
EOF
node /tmp/commit-senior-dev-fix.mjs

