input.command:
cd /home/user/rork-app
export OWNER_TOKEN=$(cat /tmp/owner_at)

echo "=== Triggering Render deploy for senior dev fix ==="
cat > /tmp/deploy-senior-dev-fix.mjs <<'EOF'
const r = await fetch('https://api.ivxholding.com/api/ivx/developer-deploy/action', {
  method: 'POST',
  headers: { 'Authorization': `Bearer ${process.env.OWNER_TOKEN}`, 'Content-Type': 'application/json' },
  body: JSON.stringify({ action: 'render_trigger_deploy', input: {}, confirm: true, confirmText: 'CONFIRM_IVX_RENDER_DEPLOY' })
});
const t = await r.text();
console.log('Deploy HTTP', r.status);
try { const j = JSON.parse(t); console.log(JSON.stringify({ok:j.ok, error:j.error, message:(j.message||'').slice(0,200)}, null, 2)); }
catch { console.log(t.slice(0,400)); }
EOF
node /tmp/deploy-senior-dev-fix.mjs

echo ""
echo "=== Current /health commit (before deploy propagates) ==="
curl -s -H "Authorization: Bearer ${OWNER_TOKEN}" https://api.ivxholding.com/health -o /tmp/h.json -w "HTTP %{http_code}\n"
node -e "const d=JSON.parse(require('fs').readFileSync('/tmp/h.json','utf8')); console.log(JSON.stringify({status:d.status,commit:(d.commit||'').slice(0,12),bootTime:d.bootTime},null,2))"

